
type ZeroRun=unsafe extern "C" fn(*const CompactOp,usize,*mut u64,*mut u64,*mut u64,usize)->i32;
fn reader(n:u64)->sha3::Shake256Reader{let mut h=Shake256::default();h.update(b"prefilter-measurement-sensitivity-v1");h.update(&n.to_le_bytes());h.finalize_xof()}
fn main(){let a:Vec<_>=std::env::args().collect();let ops=load_ops(&a[1]).unwrap();let(nq,nb,_,regs)=analyze_ops(ops.iter());let p=Compact::compile(&ops);let path=CString::new("/home/hclau/ecdsa_research/zero-mr-20261016/libzero8.so").unwrap();let handle=unsafe{dlopen(path.as_ptr(),2)};assert!(!handle.is_null());let symbol=unsafe{dlsym(handle,b"zero8_run\0".as_ptr().cast())};assert!(!symbol.is_null());let zero:ZeroRun=unsafe{std::mem::transmute(symbol)};let mut rng=vec![0u64;p.rng_count*8];for j in 0..8{let mut bytes=vec![0;p.rng_count*8];XofReader::read(&mut reader(j as u64),&mut bytes);for i in 0..p.rng_count{rng[i*8+j]=u64::from_le_bytes(bytes[i*8..i*8+8].try_into().unwrap());}}let mut out=File::create(&a[3]).unwrap();let rows:Vec<Vec<U256>>=std::fs::read_to_string(&a[2]).unwrap().lines().filter(|l|!l.trim().is_empty()).map(|l|l.split_whitespace().skip(1).map(|x|U256::from_str_radix(x.trim_start_matches("0x"),16).unwrap()).collect()).collect();let start=std::time::Instant::now();let(mut differing,mut wrongzero)=(0usize,0usize);let mut stack=vec![0;4096*8];
 for(batch,data)in rows.chunks(64).enumerate(){let mut initialq=vec![0;nq as usize*8];let mut initialb=vec![0;nb as usize*8];for(lane,row)in data.iter().enumerate(){for(reg,value)in regs[..4].iter().zip(&row[..4]){for(bit,wire)in reg.iter().enumerate(){for j in 0..8{let v=(value.bit(bit)as u64)<<lane;match wire{QubitOrBit::Qubit(id)=>initialq[id.0 as usize*8+j]|=v,QubitOrBit::Bit(id)=>initialb[id.0 as usize*8+j]|=v}}}}}let(mut randomq,mut randomb)=(initialq.clone(),initialb.clone());let mut phase=[0u64;8];let mut used=0;assert_eq!(unsafe{(exact_backend().run)(p.ops.as_ptr(),p.ops.len(),randomq.as_mut_ptr(),randomb.as_mut_ptr(),phase.as_mut_ptr(),rng.as_ptr(),p.rng_count,stack.as_mut_ptr(),4096,&mut used)},0);assert_eq!(used,p.rng_count);let(mut zeroq,mut zerob)=(initialq,initialb);assert_eq!(unsafe{zero(p.ops.as_ptr(),p.ops.len(),zeroq.as_mut_ptr(),zerob.as_mut_ptr(),stack.as_mut_ptr(),4096)},0);
 let get=|q:&[u64],b:&[u64],reg:usize,lane:usize,j:usize|{let mut value=U256::ZERO;for(bit,wire)in regs[reg].iter().enumerate(){let word=match wire{QubitOrBit::Qubit(id)=>q[id.0 as usize*8+j],QubitOrBit::Bit(id)=>b[id.0 as usize*8+j]};if word>>lane&1!=0{value|=U256::from(1)<<bit;}}value};for(lane,row)in data.iter().enumerate(){let z=[get(&zeroq,&zerob,0,lane,0),get(&zeroq,&zerob,1,lane,0)];wrongzero+=usize::from(z!=[row[4],row[5]]);let all:Vec<_>=(0..8).map(|j|[get(&randomq,&randomb,0,lane,j),get(&randomq,&randomb,1,lane,j)]).collect();for j in 1..8{assert_eq!(z,[get(&zeroq,&zerob,0,lane,j),get(&zeroq,&zerob,1,lane,j)]);}if all.iter().any(|x|*x!=z){differing+=1;let words:Vec<_>=row.iter().map(|x|format!("{x:#x}")).collect();let values:Vec<Vec<_>>=all.iter().map(|point|point.iter().map(|x|format!("{x:#x}")).collect()).collect();let record=serde_json::json!({"input_index":batch*64+lane,"input_expected":words,"zero_output":z.iter().map(|x|format!("{x:#x}")).collect::<Vec<_>>(),"random_outputs":values,"phase_samples":phase.iter().map(|x|x>>lane&1).collect::<Vec<_>>()});writeln!(out,"{record}").unwrap();}}
 }println!("{{\"source_stream\":{:?},\"inputs\":{},\"independent_mr_seeds_per_input\":8,\"zero_mr_compared\":true,\"output_value_sensitive_inputs\":{differing},\"wrong_value_under_zero_mr\":{wrongzero},\"seconds\":{:.6},\"status\":\"EMPIRICAL_DIAGNOSTIC_ONLY_NO_REJECTION_CERTIFICATE\"}}",a[1],rows.len(),start.elapsed().as_secs_f64());}
